function (startValue, durationValue, blocked, nowValue) {
  const start = new Date(startValue);
  const now = new Date(nowValue);
  const durationText = String(durationValue ?? '').trim();
  const duration = Number(durationText);
  const fail = (code, message) => ({
    available: false,
    code,
    message
  });
  if (!startValue || !nowValue || !Number.isFinite(start.getTime()) || !Number.isFinite(now.getTime())) return fail('INVALID_INPUT', 'Enter a valid start date and comparison time.');
  if (!durationText || !Number.isInteger(duration) || duration < 1 || duration > 120) return fail('INVALID_DURATION', 'Duration must be 1–120 minutes.');
  if (start <= now) return fail('PAST_START', 'Start time must be in the future.');
  const minute = start.getHours() * 60 + start.getMinutes();
  if (minute + duration > 1440) return fail('INVALID_INTERVAL', 'The interval must end by midnight.');
  if (blocked === true) return fail('BLOCKED', 'Study Room A101 is blocked.');
  if (JSObject1.bookings.some(([a, b]) => a < minute + duration && minute < b)) return fail('OVERLAP', 'Overlaps an existing booking (09:00–10:00 or 13:00–14:00).');
  return {
    available: true,
    code: 'AVAILABLE',
    message: 'Available — this interval is free.'
  };
}

